function getAudioContext(): AudioContext | null {
  if (gameContext.audioMuted) return null;
  if (!gameContext.audioCtx) {
    const AudioCtor = window.AudioContext || (window as any).webkitAudioContext;
    if (AudioCtor) {
      gameContext.audioCtx = new AudioCtor();
    }
  }
  if (gameContext.audioCtx?.state === 'suspended') {
    gameContext.audioCtx.resume();
  }
  return gameContext.audioCtx || null;
}

function playSoundClubImpact(ballSpeedMph: number) {
  const ctx = getAudioContext();
  if (!ctx) return;

  const now = ctx.currentTime;
  const speedNorm = Math.min(Math.max((ballSpeedMph - 40) / 110, 0), 1);

  // Transient Click
  const osc = ctx.createOscillator();
  const gain = ctx.createGain();
  osc.type = 'triangle';
  osc.frequency.setValueAtTime(320 + speedNorm * 180, now);
  osc.frequency.exponentialRampToValueAtTime(45, now + 0.08);

  gain.gain.setValueAtTime(0.5 + speedNorm * 0.4, now);
  gain.gain.exponentialRampToValueAtTime(0.001, now + 0.08);

  osc.connect(gain);
  gain.connect(ctx.destination);
  osc.start(now);
  osc.stop(now + 0.09);

  // Thwack Noise Burst
  const bufferSize = Math.floor(ctx.sampleRate * 0.06);
  const noiseBuffer = ctx.createBuffer(1, bufferSize, ctx.sampleRate);
  const data = noiseBuffer.getChannelData(0);
  for (let i = 0; i < bufferSize; i++) {
    data[i] = Math.random() * 2 - 1;
  }
  const noise = ctx.createBufferSource();
  noise.buffer = noiseBuffer;

  const filter = ctx.createBiquadFilter();
  filter.type = 'bandpass';
  filter.frequency.setValueAtTime(1400 + speedNorm * 800, now);
  filter.Q.setValueAtTime(3.0, now);

  const noiseGain = ctx.createGain();
  noiseGain.gain.setValueAtTime(0.4 + speedNorm * 0.3, now);
  noiseGain.gain.exponentialRampToValueAtTime(0.001, now + 0.06);

  noise.connect(filter);
  filter.connect(noiseGain);
  noiseGain.connect(ctx.destination);
  noise.start(now);
}

