async function setupWorld() {
  gameContext.timer.connect(document);

  const canvas = document.getElementById('canvas');
  if (!canvas || !(canvas instanceof HTMLCanvasElement)) {
    throw new Error('Canvas element missing or invalid');
  }

  // Determine initial graphics quality (URL param -> localStorage -> setupData -> default Epic)
  let initialQuality = QualityMode.Epic;
  try {
    const urlParams = new URLSearchParams(window.location.search);
    const qParam = urlParams.get('quality');
    const storedQ = typeof localStorage !== 'undefined' ? localStorage.getItem('ogs_graphics_quality') : null;
    initialQuality = parseQuality(qParam || storedQ || gameContext.setupData?.qualityLevel || 'epic');
  } catch (e) {
    initialQuality = QualityMode.Epic;
  }
  gameContext.currentQuality = initialQuality;

  gameContext.renderer = new FuseRenderer({
    canvas,
    adaptive: true,
    renderMode: 'webgpu',
    forceWebGL: gameContext.setupData?.backend === 'webgl',
    qualityLevel: initialQuality,
  });

  await gameContext.renderer.init();
}

async function createDrivingRange() {
  if (!gameContext.scene) return;

  // High-fidelity procedural fairway turf with crisp mowing stripes & micro-blade normals
  const fairwayTextures = getProceduralFairwayTextures(gameContext.renderer?.getMaxAnisotropy() || 8);
  fairwayTextures.map.repeat.set(65, 130);
  fairwayTextures.normalMap.repeat.set(65, 130);

  const floorMaterial = new THREE.MeshStandardMaterial({
    map: fairwayTextures.map,
    normalMap: fairwayTextures.normalMap,
    normalScale: new THREE.Vector2(0.65, 0.65),
    roughness: 0.70,
    metalness: 0.04,
  });

  // Expanded Range grid 550m wide x 1100m long, centered at Z = 450m (extends from Z=-100m to Z=+1000m)
  const floorGeometry = new THREE.PlaneGeometry(550, 1100, 50, 100);
  gameContext.ground = new THREE.Mesh(floorGeometry, floorMaterial);
  gameContext.ground.rotation.x = -Math.PI / 2;
  gameContext.ground.position.set(0, 0, 450);
  gameContext.ground.receiveShadow = true;
  gameContext.ground.userData.surface = 'fairway';
  gameContext.scene.add(gameContext.ground);

  // AAA Stadium Night Sky Dome with twinkling stars and atmospheric horizon glow
  gameContext.atmosphere = createStadiumAtmosphere(gameContext.scene, 850);

  // Volumetric Floodlight Beams down both sides of the range
  gameContext.volumetricBeams = [];
  [30, 80, 140, 200, 260, 320].forEach((z) => {
    [-45, 45].forEach((x) => {
      const beam = createVolumetricLightBeam(16, 0.08, 12.0, 0xfef08a);
      beam.position.set(x, 16, z);
      gameContext.scene.add(beam);
      gameContext.volumetricBeams.push(beam);
    });
  });

  // Background mountains (pushed back to Z=920m with scale 28x with deep midnight silhouette)
  try {
    const mountain = await gameContext.meshLoader?.load(rangeMtnsModel, true);
    if (mountain) {
      mountain.position.set(0, -10, 920);
      mountain.scale.set(28, 28, 28);
      mountain.traverse((child) => {
        if ((child as THREE.Mesh).isMesh) {
          const mesh = child as THREE.Mesh;
          mesh.material = new THREE.MeshBasicMaterial({
            color: new THREE.Color('#060e22'),
          });
        }
      });
      gameContext.scene.add(mountain);
    }
  } catch (err) {
    console.warn('Could not load mountains:', err);
  }

  // Visual Shockwave for Flag Captures
  const shockGeo = new THREE.RingGeometry(0.3, 0.9, 32);
  shockGeo.rotateX(-Math.PI / 2);
  const shockMat = new THREE.MeshBasicMaterial({
    color: new THREE.Color('#f59e0b'),
    transparent: true,
    opacity: 0,
    side: THREE.DoubleSide,
  });
  gameContext.shockwaveMesh = new THREE.Mesh(shockGeo, shockMat);
  gameContext.shockwaveMesh.position.set(0, 0.05, 0);
  gameContext.scene.add(gameContext.shockwaveMesh);

  // Setup Fireworks / Sparks Particle System
  setupParticleSystem();

  // Setup Proximity Tether Line, Distance Billboard & Ball Light
  setupProximityVisuals();
}

function setupProximityVisuals() {
  if (!gameContext.scene) return;

  // 1. Dynamic 3D Glowing Tether Line
  const tetherGeo = new THREE.BufferGeometry();
  tetherGeo.setAttribute('position', new THREE.BufferAttribute(new Float32Array(6), 3));
  const tetherMat = new THREE.LineBasicMaterial({
    color: new THREE.Color('#facc15'),
    linewidth: 2,
    transparent: true,
    opacity: 0.9,
    blending: THREE.AdditiveBlending,
  });
  const tetherLine = new THREE.Line(tetherGeo, tetherMat);
  tetherLine.visible = false;
  gameContext.scene.add(tetherLine);
  gameContext.proximityTetherLine = tetherLine;

  // 2. Dynamic 3D Proximity Billboard Sprite (512x128 high-res canvas)
  const canvas = document.createElement('canvas');
  canvas.width = 512;
  canvas.height = 128;
  const texture = new THREE.CanvasTexture(canvas);
  const spriteMat = new THREE.SpriteMaterial({ map: texture, transparent: true, depthTest: true });
  const sprite = new THREE.Sprite(spriteMat);
  sprite.scale.set(2.8, 0.7, 1);
  sprite.visible = false;
  gameContext.scene.add(sprite);
  gameContext.proximitySprite = sprite;
  gameContext.proximityCanvas = canvas;
  gameContext.proximityTexture = texture;

  // 3. Team Point Light for In-Flight Ball Glow
  const ballLight = new THREE.PointLight(0xffffff, 0, 18, 1.8);
  gameContext.scene.add(ballLight);
  gameContext.ballPointLight = ballLight;
}

// Particle System for 3D Celebrations
function setupParticleSystem() {
  if (!gameContext.scene) return;

  const maxParticles = 80;
  const positions = new Float32Array(maxParticles * 3);
  const colors = new Float32Array(maxParticles * 3);

  gameContext.particleGeo = new THREE.BufferGeometry();
  gameContext.particleGeo.setAttribute('position', new THREE.BufferAttribute(positions, 3));
  gameContext.particleGeo.setAttribute('color', new THREE.BufferAttribute(colors, 3));

  const mat = new THREE.PointsMaterial({
    size: 0.4,
    vertexColors: true,
    transparent: true,
    opacity: 0.9,
    blending: THREE.AdditiveBlending,
  });

  gameContext.particlePoints = new THREE.Points(gameContext.particleGeo, mat);
  gameContext.scene.add(gameContext.particlePoints);
}

function spawnCaptureParticles(origin: THREE.Vector3, colorHex: string) {
  const count = 40;
  const baseColor = new THREE.Color(colorHex);

  for (let i = 0; i < count; i++) {
    const angle = Math.random() * Math.PI * 2;
    const speed = 3 + Math.random() * 8;
    const upward = 6 + Math.random() * 9;

    gameContext.particles.push({
      pos: new THREE.Vector3(origin.x, origin.y + 0.4, origin.z),
      vel: new THREE.Vector3(
        Math.cos(angle) * speed,
        upward,
        Math.sin(angle) * speed
      ),
      color: baseColor.clone(),
      life: 0,
      maxLife: 1.2 + Math.random() * 0.8,
    });
  }
}

function updateParticles(delta: number) {
  if (!gameContext.particlePoints || !gameContext.particleGeo) return;

  const gravity = -9.81;
  const active: SparkParticle[] = [];

  for (let i = 0; i < gameContext.particles.length; i++) {
    const p = gameContext.particles[i];
    p.life += delta;
    if (p.life < p.maxLife) {
      p.vel.y += gravity * delta;
      p.pos.addScaledVector(p.vel, delta);
      active.push(p);
    }
  }
  gameContext.particles = active;

  const posAttr = gameContext.particleGeo.attributes.position as THREE.BufferAttribute;
  const colAttr = gameContext.particleGeo.attributes.color as THREE.BufferAttribute;

  for (let i = 0; i < 80; i++) {
    if (i < active.length) {
      const p = active[i];
      posAttr.setXYZ(i, p.pos.x, p.pos.y, p.pos.z);
      const alpha = 1 - (p.life / p.maxLife);
      colAttr.setXYZ(i, p.color.r * alpha, p.color.g * alpha, p.color.b * alpha);
    } else {
      posAttr.setXYZ(i, 0, -100, 0);
    }
  }

  posAttr.needsUpdate = true;
  colAttr.needsUpdate = true;
}

// Create a 3D Canvas Sprite for distance marker above each flag
function createDistanceSignSprite(text: string): THREE.Sprite {
  const canvas = document.createElement('canvas');
  canvas.width = 256;
  canvas.height = 128;
  const ctx = canvas.getContext('2d');
  if (ctx) {
    ctx.fillStyle = 'rgba(15, 23, 42, 0.88)';
    ctx.roundRect ? ctx.roundRect(10, 10, 236, 108, 20) : ctx.rect(10, 10, 236, 108);
    ctx.fill();
    ctx.lineWidth = 6;
    ctx.strokeStyle = '#f59e0b';
    ctx.stroke();

    ctx.font = 'bold 54px -apple-system, sans-serif';
    ctx.fillStyle = '#ffffff';
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    ctx.fillText(text, 128, 64);
  }
  const texture = new THREE.CanvasTexture(canvas);
  const spriteMat = new THREE.SpriteMaterial({ map: texture, transparent: true });
  const sprite = new THREE.Sprite(spriteMat);
  sprite.scale.set(3.8, 1.9, 1);
  sprite.position.set(0, 3.4, 0);
  return sprite;
}

